import { Game, Logger, Node, REFERENCE_ILLUMINANCE, aimFromDirection, clamp, lerp } from 'cleo'

/**
 * Night Shift — the level director. Attach to an empty node named `GameManager` at the scene root.
 *
 * One authoritative clock, one score, one place that decides the level is over. Everything else in the
 * game reads this node: the HUD, the spawner, the pickups and the end screen all find it once in
 * `onStart` and cache it. Nothing calls `findNode` per frame.
 *
 * ## The night
 *
 * A level is a fixed span of real time mapped linearly onto a clock, so difficulty scales through spawn
 * rate alone and nothing feeds back into the clock:
 *
 *   t         = elapsed / levelSeconds        0..1
 *   clockHour = startHour + t * nightHours    22:00 -> 06:00
 *   elevation = lerp(nightElevation, dayElevation, t)
 *   isDay     = elevation >= 0
 *
 * ## Why the sun is stepped on a timer and not in onUpdate
 *
 * The sky atmosphere bakes six cube faces of raymarched scattering plus a mip chain whenever the sun
 * moves, and the ONLY throttle is angular — it re-bakes once the sun has rotated ~0.3 degrees. Writing
 * `sunDirection`, `sunColor`, `sunIntensity`, the sky node's `exposure` or `groundColor` sets the bake
 * flag UNCONDITIONALLY, and that check short-circuits ahead of the angular one, so touching any of them
 * every frame bakes every frame.
 *
 * So we never touch those setters. We rotate the scene's directional light, which `useSceneSun` reads,
 * and that path is the only one the angular epsilon actually guards. Stepping it on a coarse timer keeps
 * the re-bake to roughly once a second even on a short night.
 *
 * Sky ambient is a second trap: the spherical-harmonic projection decides it is stale by comparing
 * cubemap OBJECT IDENTITY, and the re-bake renders into the same texture — so indirect light would freeze
 * at the first sun position forever. `markDirty()` on its own slow cadence is what keeps night dark.
 *
 * Renderer exposure/saturation/vignette are a different surface from the sky node's `exposure` and cost
 * nothing, so the dusk-to-dawn mood rides those per frame.
 */
export default class NightShiftDirectorNode extends Node {
  /** Real seconds from dusk to dawn. The whole level. */
  public levelSeconds: number = 180
  /** Clock hour the night starts at. */
  public startHour: number = 22
  /** Hours of game time the night spans. 22:00 + 8 = 06:00. */
  public nightHours: number = 8
  /** Sun elevation in degrees at t=0. Well below the horizon. */
  public nightElevation: number = -25
  /** Sun elevation in degrees at t=1. */
  public dayElevation: number = 20
  /** Compass direction the sun rises from, in degrees. */
  public sunAzimuth: number = 95
  /**
   * Sun brightness in LUX. Lights are photometric: `DEFAULT_DIRECTIONAL_LUX` is 100000 and the
   * renderer's reference illuminance is 78643, so a value in the single digits is not "dim", it is
   * black. Real moonlight is under a lux and unplayable, so this is a stylised moon about two and a
   * half stops under daylight — still night once exposure and saturation come down with it.
   */
  public nightLux: number = 6000
  public dayLux: number = 100000
  /**
   * Ambient, as a FRACTION of the reference illuminance so these read as the fractions they are.
   *
   * `nightAmbient` is doing nearly all the work, and it has to. For most of the night the sun is BELOW
   * the horizon, and a directional light below the horizon has `N dot L < 0` on every upward-facing
   * surface — so the ground receives essentially nothing from it however high `nightLux` goes. Ambient
   * is omnidirectional and is what you actually see by until the sun crosses over near dawn.
   *
   * Turning the night up means turning THIS up, not `nightLux`. The engine's own default scene ambient
   * is 0.1 of the reference, so a night sitting at half that is dim without being unreadable.
   */
  public nightAmbient: number = 0.05
  public dayAmbient: number = 0.16
  /** How many pickups the level was authored with. The HUD shows `found / total`. */
  public itemsTotal: number = 12
  /** Which level this is. Raises the spawn rate; persisted across a Continue. */
  public level: number = 1
  /** Seconds between sun steps. Small enough to look continuous, large enough not to thrash the bake. */
  public sunStepSeconds: number = 0.25
  /** Seconds between sky-ambient refreshes. Does a GPU readback, so keep it slow. */
  public ambientStepSeconds: number = 2
  /** Name of the scene loaded by the Exit button. */
  public menuScene: string = 'Main Menu'
  /** Report the lighting state once on start. Cheap, and the first thing to read if the level is dark. */
  public logLighting: boolean = true

  /** Points banked so far. */
  public score: number = 0
  /** Pickups collected so far. */
  public itemsFound: number = 0
  /** True once the level is over, either way. Gates the spawner and the clock. */
  public finished: boolean = false

  private _elapsed: number = 0
  private _sun: Node = null
  private _end: Node = null
  private _restoreRender: any = null

  onStart() {
    // The level number survives Game.loadScene, which resets every script. localStorage is the only
    // thing that does — the alternative is one scene per level.
    try {
      const saved = parseInt(window.localStorage.getItem('nightShift.level') || '', 10)
      if (isFinite(saved) && saved > 0) this.level = saved
    } catch { /* private mode, or no DOM — the default level stands */ }

    this._sun = this.findNode('Sun')
    this._end = this.findNode('EndScreen')
    if (!this._sun) Logger.warn('Night Shift: no node named "Sun" — the sky will not move.', 'Script')

    // Render settings live on the RENDERER, not the scene — one global the editor viewport shares with
    // Play. Ramping them without putting them back leaves the editor stuck at whatever the level last
    // looked like, which reads as "the scene went dark after I played it once".
    const current = Game.getRenderSettings()
    if (current) {
      this._restoreRender = {
        exposure: current.exposure,
        saturation: current.saturation,
        vignetteStrength: current.vignetteStrength,
      }
    }

    this._applySun()
    if (this.logLighting) this._reportLighting()
    this.every(this.sunStepSeconds, () => this._applySun())
    this.every(this.ambientStepSeconds, () => this.scene?.skyLight?.markDirty())
  }

  onUpdate(delta: number, time: number) {
    if (this.finished) return

    this._elapsed += delta
    const t = this.progress

    // Free every frame: none of these touch the sky node, so none of them can trigger a re-bake.
    //
    // Exposure OPENS at night and stops down toward dawn, the way a camera would — but only slightly.
    // Exposure is a correction, not the lighting: leaning on it to carry a night flattens the contrast
    // between the lit and unlit parts of the scene and washes the whole frame out. The darkness comes
    // from `nightAmbient` and a sun under the horizon; this just keeps it readable.
    Game.updateRenderSettings({
      exposure: lerp(1.6, 1.3, t),
      saturation: lerp(0.55, 1.0, t),
      vignetteStrength: lerp(0.4, 0.15, t),
    })

    if (t >= 1) this.endLevel(true)
  }

  /**
   * One line describing everything that decides how bright the level is.
   *
   * A dark scene has several possible causes that all look identical from the outside — an intensity in
   * the wrong unit, an ambient that is being overridden, an exposure running the wrong way — so this
   * prints the actual numbers rather than leaving it to be guessed at.
   *
   * `probes` is the one to watch: a light probe REPLACES the scene ambient for every pixel inside its
   * volume, so any non-zero count means `ambient` below is not what is lighting the player.
   */
  private _reportLighting(): void {
    const light = (this._sun as any)?.light
    const ambient = this.scene?.ambientLight
    Logger.info(
      'Night Shift lighting: elevation ' + this.sunElevation.toFixed(1) + ' deg'
      + ' | sun ' + (light ? Math.round(light.intensity) + ' lux' : 'NO SUN NODE')
      + ' | ambient ' + (ambient ? Math.round(Math.max(ambient[0], ambient[1], ambient[2])) + ' lux' : 'unset')
      + ' | exposure ' + (Game.getRenderSettings()?.exposure ?? '?')
      + ' | probes ' + (this.scene?.lightProbes?.size ?? 0)
      + ' | skyLight ' + (this.scene?.skyLight ? this.scene.skyLight.intensity.toFixed(2) : 'none'),
      'Script')
  }

  /** 0 at dusk, 1 at dawn. */
  public get progress(): number {
    return clamp(this._elapsed / Math.max(0.001, this.levelSeconds), 0, 1)
  }

  /** The clock as `HH:MM`, wrapping past midnight. */
  public get clockText(): string {
    const hour = this.startHour + this.progress * this.nightHours
    const h = Math.floor(hour) % 24
    const m = Math.floor((hour - Math.floor(hour)) * 60)
    return (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m
  }

  /** Sun elevation in degrees. Negative is below the horizon. */
  public get sunElevation(): number {
    return lerp(this.nightElevation, this.dayElevation, this.progress)
  }

  /**
   * True once the sun is above the horizon. The spawner stops and every zombie catches fire on it.
   *
   * DERIVED from the clock, deliberately, rather than stamped by `_applySun`. Stamping it there would
   * make a gameplay rule depend on a rendering node existing: rename or delete the Sun light and the
   * night would never end, the zombies would never burn, and nothing would say why.
   */
  public get isDay(): boolean {
    return this.sunElevation >= 0
  }

  onDespawn() {
    // Play has stopped. Hand the viewport back the look it had before this level started.
    if (this._restoreRender) Game.updateRenderSettings(this._restoreRender)
  }

  public addScore(points: number): void {
    this.score += points
    this.itemsFound++
  }

  /**
   * End the level. `won` picks the panel's wording and which button the player gets.
   *
   * Pausing freezes every `onUpdate` and the health bar's smoothing but NOT the UI layout pass, and
   * button clicks arrive through the DOM rather than the node loop — so the panel still lays out and
   * still responds while the game behind it is stopped.
   */
  public endLevel(won: boolean): void {
    if (this.finished) return
    this.finished = true

    try {
      window.localStorage.setItem('nightShift.level', String(won ? this.level + 1 : this.level))
    } catch { /* nothing to persist to; Continue will restart at level 1 */ }

    const end = this._end as any
    if (end && end.showResult) end.showResult(won, this.itemsFound, this.itemsTotal, this.score, this.level)
    else Logger.warn('Night Shift: no EndScreen in the scene, so the level just stops.', 'Script')

    Game.pause()
  }

  /**
   * Point the directional light along the sun's travel.
   *
   * `aimFromDirection` is the inverse of the engine's euler-to-forward mapping, so feeding it the
   * direction light TRAVELS (the negated direction toward the sun) and writing the result as
   * `[pitch, yaw, 0]` round-trips exactly. Reading `rotation[1]` back would not — the decomposition
   * cannot express a yaw past a quarter turn.
   */
  private _applySun(): void {
    if (this.finished || !this._sun) return

    const elevation = this.sunElevation
    const e = elevation * Math.PI / 180
    const a = this.sunAzimuth * Math.PI / 180
    // Direction TOWARD the sun; the light travels the other way.
    const toSun: [number, number, number] = [Math.cos(e) * Math.sin(a), Math.sin(e), Math.cos(e) * Math.cos(a)]
    const aim = aimFromDirection([-toSun[0], -toSun[1], -toSun[2]] as any)
    this._sun.setRotation([aim.pitch, aim.yaw, 0])

    // Colour and brightness are on the LIGHT, not the sky node, so they are free of the bake.
    const light = (this._sun as any).light
    if (!light) return
    const day = clamp((elevation + 6) / 12, 0, 1)
    light.intensity = lerp(this.nightLux, this.dayLux, day)
    light.color = [lerp(0.42, 1, day), lerp(0.5, 0.96, day), lerp(0.85, 0.86, day)]

    // Ambient is in LUX too. Leaving the scene's value unset gives the engine's own
    // DEFAULT_SCENE_AMBIENT_LUX (a tenth of the reference); writing a raw 0.06 gives darkness.
    if (this.scene) {
      const ambient = lerp(this.nightAmbient, this.dayAmbient, day) * REFERENCE_ILLUMINANCE
      this.scene.ambientLight = [ambient * 0.82, ambient * 0.9, ambient * 1.15]
    }

    const sky = this.scene?.skyLight
    if (sky) sky.intensity = lerp(0.35, 1, day)
  }
}

import { CharacterNode, Logger, Node } from 'cleo'

/**
 * Night Shift — the playable. Attach to the `Playable` root, which must be a Character node.
 *
 * Movement is not here and must not be: locomotion lives in `CharacterNode` itself and writes the body's
 * velocity every frame, so a second writer produces a character that stutters. This script owns the
 * things locomotion has no opinion about — health, powerups, and dying.
 *
 * See `ThirdPersonPlayable.ts` and `examples/scripts/README.md` for the body setup this depends on
 * (capsule collider, friction 0, linearConstraints [1,1,1]).
 *
 * ## The `isPlayer` marker
 *
 * The engine has no faction system: the perception pass offers every other Character as a candidate, so
 * a zombie's brain would happily target another zombie. `NightShiftZombieBrain` filters on this node
 * variable, which is set here rather than authored so it can never be lost in a scene edit. It is a
 * VARIABLE and not a field on purpose — `getVariable` works across nodes without a cast.
 */
export default class NightShiftPlayerNode extends CharacterNode {
  public maxHealth: number = 100
  public health: number = 100
  /** True while an Invincibility powerup is running. The zombie's damage check reads it. */
  public invincible: boolean = false
  /** Multiplier applied to walk and run speed while a Speed powerup is running. */
  public speedMultiplier: number = 1.7
  /** Seconds a Speed powerup lasts. */
  public speedSeconds: number = 8
  /** Seconds an Invincibility powerup lasts. */
  public invincibleSeconds: number = 6
  /** How long the AoE pip stays lit after a blast, purely so the HUD has something to show. */
  public aoeFlashSeconds: number = 1.5

  /** Seconds left on each powerup. The HUD reads these to fill its pips. */
  public speedLeft: number = 0
  public invincibleLeft: number = 0
  public aoeLeft: number = 0

  private _baseWalk: number = 0
  private _baseRun: number = 0
  private _dead: boolean = false
  private _director: Node = null

  onStart() {
    this.setVariable('isPlayer', true, 'boolean', 'public')
    this._baseWalk = this.walkSpeed
    this._baseRun = this.runSpeed
    this._director = this.findNode('GameManager')
    this.health = this.maxHealth
  }

  onUpdate(delta: number, time: number) {
    if (this.speedLeft > 0) {
      this.speedLeft -= delta
      if (this.speedLeft <= 0) this._endSpeed()
    }
    if (this.invincibleLeft > 0) {
      this.invincibleLeft -= delta
      if (this.invincibleLeft <= 0) {
        this.invincibleLeft = 0
        this.invincible = false
      }
    }
    if (this.aoeLeft > 0) this.aoeLeft = Math.max(0, this.aoeLeft - delta)
  }

  /** Called by the zombie. Returns true if the hit landed, so the caller can play a reaction. */
  public damage(amount: number): boolean {
    if (this._dead || this.invincible || amount <= 0) return false

    this.health = Math.max(0, this.health - amount)
    if (this.health > 0) return true

    this._dead = true
    const director = this._director as any
    if (director && director.endLevel) director.endLevel(false)
    else Logger.warn('Night Shift: player died with no GameManager to tell.', 'Script')
    return true
  }

  /** Speed and Invincibility both re-arm rather than stack, which is what a player expects. */
  public grantSpeed(): void {
    if (this.speedLeft <= 0) {
      this._baseWalk = this.walkSpeed
      this._baseRun = this.runSpeed
      this.walkSpeed = this._baseWalk * this.speedMultiplier
      this.runSpeed = this._baseRun * this.speedMultiplier
    }
    this.speedLeft = this.speedSeconds
  }

  public grantInvincibility(): void {
    this.invincible = true
    this.invincibleLeft = this.invincibleSeconds
  }

  /** Lights the AoE pip. The blast itself is the powerup's job — it owns the radius. */
  public flashAoe(): void {
    this.aoeLeft = this.aoeFlashSeconds
  }

  /**
   * Restore the authored speeds rather than dividing back out: repeated pickups would otherwise drift
   * the base upward through floating-point error, and a pickup taken while one is already running would
   * compound the multiplier.
   */
  private _endSpeed(): void {
    this.speedLeft = 0
    this.walkSpeed = this._baseWalk
    this.runSpeed = this._baseRun
  }
}

import { CharacterNode, Logger, ModelNode, Node, clamp, lerp } from 'cleo'

/**
 * Night Shift — a zombie. Attach to the `Zombie` root of the Zombie template, which is a Character node.
 *
 * Movement, chasing and attacking-position are the behaviour machine's job on the sibling Controller;
 * this script owns only what a machine cannot express: dealing damage, catching fire, and dying.
 *
 * ## Attacking without an attack clip
 *
 * There is no attack animation in this project, so damage runs on a cooldown while the brain holds its
 * `Attack` state, and the pose stays Idle. The range is re-checked at the moment of the hit rather than
 * trusted from the state transition, so backing away mid-swing genuinely avoids it.
 *
 * ## Burning
 *
 * The engine has no particle system, so fire is three cheap layers: an emissive ramp on the material, a
 * billboarded flame sprite, and a flickering point light. All three are already in this project.
 *
 * The emissive ramp is safe per zombie because `Scene.instantiate` makes a COMPLETE copy — children,
 * materials, colliders and scripts, with fresh ids — so nothing is shared with the template or with the
 * other instances. Every submesh material is walked, not just `materials[0]`, or a multi-material
 * zombie would burn in patches.
 *
 * ## Dying without a death clip
 *
 * There is no death animation either, so death is a RAGDOLL — the mannequin already carries a full
 * ragdoll configuration. `startRagdoll` puts the animator into ragdoll mode and hands the skeleton to
 * physics, which is a better corpse than any single clip anyway.
 */
export default class NightShiftZombieNode extends CharacterNode {
  /** Damage per successful hit. */
  public damage: number = 12
  /** Seconds between hits while in range. */
  public attackCooldown: number = 1.2
  /** Metres. Re-checked when the hit lands, not when the state was entered. */
  public attackRange: number = 2
  /** Seconds from ignition to death. */
  public burnSeconds: number = 3.5
  /** Seconds the ragdoll is left lying before the node is removed. */
  public corpseSeconds: number = 6
  /** Set by the director at dawn, and by the AoE powerup. The behaviour machine reads it as a builtin. */
  public burning: boolean = false

  private _cooldown: number = 0
  private _burnedFor: number = 0
  private _dying: boolean = false
  private _player: Node = null
  private _brain: Node = null
  private _model: ModelNode = null
  private _flame: Node = null
  private _fireLight: Node = null

  onStart() {
    this._player = this.findNode('Playable')
    this._brain = this.getChildByName('Brain')[0]
    this._model = this.getChildByName('Ch36')[0] as ModelNode
    this._flame = this.getChildByName('Flame')[0]
    this._fireLight = this.getChildByName('Fire Light')[0]

    // Authored visible so they are easy to find in the editor; hidden until the zombie actually burns.
    if (this._flame) this._flame.visible = false
    if (this._fireLight) this._fireLight.visible = false
  }

  onUpdate(delta: number, time: number) {
    if (this._dying) return
    if (this.burning) { this._burn(delta); return }

    this._cooldown = Math.max(0, this._cooldown - delta)
    const brain = this._brain as any
    if (!brain || brain.behaviorState !== 'Attack') return
    if (this._cooldown > 0) return

    const player = this._player as any
    if (!player || !player.damage) return
    if (this._planarDistanceTo(this._player) > this.attackRange) return

    this._cooldown = this.attackCooldown
    player.damage(this.damage)
  }

  /** Ignite. Idempotent — the AoE blast and dawn can both name the same zombie in one frame. */
  public ignite(): void {
    if (this.burning || this._dying) return
    this.burning = true
    this._burnedFor = 0
    if (this._flame) this._flame.visible = true
    if (this._fireLight) this._fireLight.visible = true
  }

  private _burn(delta: number): void {
    this._burnedFor += delta
    const t = clamp(this._burnedFor / Math.max(0.001, this.burnSeconds), 0, 1)

    // Well above 1, or it clamps to white instead of blooming.
    const glow = lerp(0.5, 7, t)
    const materials = this._model?.model?.materials
    if (materials) {
      for (const material of materials) {
        // The key differs by shading model, and writing the wrong one is silently ignored.
        if (material.properties.has('emissiveFactor')) {
          material.properties.set('emissiveFactor', [1, lerp(0.5, 0.18, t), 0.05])
          material.properties.set('emissiveIntensity', glow)
        } else {
          material.properties.set('emissive', [glow, glow * lerp(0.5, 0.18, t), glow * 0.05])
        }
      }
    }

    const light = (this._fireLight as any)?.light
    // A cheap flicker: two out-of-phase sines beat a random, which reads as noise rather than fire.
    if (light) light.intensity = lerp(400, 90, t) * (0.75 + 0.25 * Math.sin(this._burnedFor * 21)
      + 0.12 * Math.sin(this._burnedFor * 37))

    if (t >= 1) this._die()
  }

  private _die(): void {
    if (this._dying) return
    this._dying = true

    // Stop steering a corpse. Releasing the pawn also stops the controller thinking about it.
    const brain = this._brain as any
    if (brain && brain.release) brain.release()
    this.velocity = [0, 0, 0]

    const physics = this.scene?.physics as any
    if (physics && physics.startRagdoll && this._model) {
      try { physics.startRagdoll(this._model) }
      catch (e) { Logger.warn('Night Shift: ragdoll failed, falling back to a still corpse: ' + e, 'Script') }
    }

    if (this._flame) this._flame.visible = false
    if (this._fireLight) this._fireLight.visible = false

    // Scheduled on this node, which is the thing being removed — that is fine, because `remove()` is
    // what the timer DOES. A restore timer would have to live elsewhere; see NightShiftPowerup.
    this.after(this.corpseSeconds, () => this.remove())
  }

  private _planarDistanceTo(other: Node): number {
    if (!other) return Infinity
    const a = this.worldPosition
    const b = other.worldPosition
    return Math.hypot(b[0] - a[0], b[2] - a[2])
  }
}

import { ControllerNode, Node } from 'cleo'

/**
 * Night Shift — the zombie's driver. Attach to the `Brain` child of the Zombie template, on a Controller
 * node with Source: AI.
 *
 * This exists for one reason: **the engine has no faction system.** `ControllerNode.perceive` offers
 * every other Character in the scene as a perception candidate, and the built-in `autoAcquire` takes the
 * nearest NOTICED one. Zombies are Characters, so with auto-acquire left on, zombies target each other
 * and the horde mills around itself while the player walks past untouched.
 *
 * So the template sets `autoAcquire = false` and acquisition happens here instead, filtered to nodes
 * carrying an `isPlayer` variable (set by `NightShiftPlayer.onStart`). Matching on a variable rather than
 * on the node's name means renaming the Playable cannot silently blind every zombie.
 *
 * ## Why `onThink`
 *
 * It runs LAST in the control pass, after possession, the aim basis and this frame's perception are all
 * resolved, and before any node's `onUpdate` reads the result. Writing the blackboard anywhere else
 * would act on the previous frame's senses.
 *
 * ## Why a target is kept after it goes out of sight
 *
 * `investigate` walks to where the target was last seen, and it can only do that while the blackboard
 * still names it. Dropping the target the moment line of sight breaks is what makes an agent forget you
 * the instant you round a corner — the memory span exists precisely to stop that. So a held target is
 * kept until perception has genuinely forgotten it.
 *
 * The engine's own `_acquire` uses `Perception.remembers` for that test, but `ControllerNode._perception`
 * is private and `sightingOf` is not re-exposed on the controller. `sightings` is, and it carries
 * `timeSinceSeen`, so the same question is answered here directly.
 */
export default class NightShiftZombieBrainNode extends ControllerNode {
  /** Node variable that marks something worth hunting. */
  public targetMarker: string = 'isPlayer'

  onThink(delta: number) {
    const key = this.targetKey
    const held = this.getBlackboard(key)
    const heldId = typeof held === 'string' && held ? held : null

    const self = this.possessed ? this.possessed.worldPosition : this.worldPosition
    let bestId: string = null
    let bestDistance: number = Infinity
    let heldRemembered: boolean = false

    for (const sighting of this.sightings) {
      const candidate = this.scene?.getNodeById(sighting.id)
      if (!candidate || !candidate.getVariable(this.targetMarker)) continue

      // `timeSinceSeen` is 0 while visible and Infinity if never seen, so this covers both.
      if (sighting.id === heldId && sighting.timeSinceSeen <= this.perception.memorySpan) {
        heldRemembered = true
      }

      if (!sighting.noticed) continue
      const p = candidate.worldPosition
      const distance = Math.hypot(p[0] - self[0], p[1] - self[1], p[2] - self[2])
      if (distance < bestDistance) {
        bestDistance = distance
        bestId = sighting.id
      }
    }

    if (bestId) { this.setBlackboard(key, bestId); return }
    // Nothing in sight. Hold the last target until its memory lapses, then genuinely forget it.
    if (heldId && !heldRemembered) this.setBlackboard(key, undefined)
  }
}

import { Logger, Node, clamp, lerp } from 'cleo'

/**
 * Night Shift — the zombie spawner. Attach to an empty node named `ZombieSpawner` at the scene root.
 *
 * It sits on its own node deliberately. Timers are cancelled when their node despawns, so a spawner that
 * lived on a zombie would stop scheduling the moment that zombie died.
 *
 * ## The curve
 *
 *   interval = baseInterval / (1 + levelRamp * (level - 1))    harder every level
 *   interval *= lerp(nightStart, nightEnd, t)                  and harder as the night wears on
 *
 * `every()` cannot express that, because the period would be fixed at the moment it was scheduled. A
 * self-rescheduling `after()` re-reads the curve on each tick, which is the whole point.
 *
 * ## Placement
 *
 * Spawn points come from the navmesh when one is baked — `randomPoint` only ever returns somewhere
 * genuinely walkable — and fall back to authored `Spawn Point` child nodes otherwise, so the level works
 * on a scene nobody has baked yet. Either way a candidate closer to the player than `minPlayerDistance`
 * is rejected, so nothing ever materialises in your face.
 */
export default class NightShiftSpawnerNode extends Node {
  /** Template name to instantiate. */
  public templateName: string = 'Zombie'
  /** Seconds between spawns at level 1, at dusk. */
  public baseInterval: number = 6
  /** How much each level past the first compresses the interval. */
  public levelRamp: number = 0.35
  /** Interval multiplier at dusk. */
  public nightStart: number = 1.4
  /** Interval multiplier at dawn. Below 1, so the night tightens. */
  public nightEnd: number = 0.6
  /** Never spawn faster than this, whatever the level. */
  public minInterval: number = 0.8
  /** Hard cap on live zombies. Each one costs a think, a perception step and a few raycasts a frame. */
  public maxAlive: number = 14
  /** Metres. A candidate closer than this to the player is rejected. */
  public minPlayerDistance: number = 18
  /** How many placements to try before giving up for this tick. */
  public placementTries: number = 12
  /** Radius of the authored-spawn-point fallback scatter, in metres. */
  public fallbackRadius: number = 45

  private _director: Node = null
  private _player: Node = null
  private _points: Node[] = []
  private _live: Node[] = []

  onStart() {
    this._director = this.findNode('GameManager')
    this._player = this.findNode('Playable')
    this._points = this.getChildByName('Spawn Point')
    this.after(this.intervalSeconds(), () => this._tick())
  }

  private _tick(): void {
    const director = this._director as any
    if (director && director.finished) return

    // Drop the ones that removed themselves, so `maxAlive` counts what is actually walking around.
    this._live = this._live.filter(z => z && z.scene && !z.markForRemoval)

    if (!director?.isDay && this._live.length < this.maxAlive) this._spawnOne()
    this.after(this.intervalSeconds(), () => this._tick())
  }

  /**
   * Seconds until the next spawn, re-read on every tick so the curve can move under it.
   * Public because it is the whole difficulty model and deserves a test of its own.
   */
  public intervalSeconds(): number {
    const director = this._director as any
    const level = Math.max(1, director?.level ?? 1)
    const t = clamp(director?.progress ?? 0, 0, 1)
    const base = this.baseInterval / (1 + this.levelRamp * (level - 1))
    return Math.max(this.minInterval, base * lerp(this.nightStart, this.nightEnd, t))
  }

  private _spawnOne(): void {
    const at = this._pickPoint()
    if (!at) return

    const zombie = this.scene?.instantiate(this.templateName, {
      position: at,
      rotation: [0, Math.random() * 360, 0],
    })
    if (!zombie) {
      // instantiate already logged the available template names; say why we are giving up.
      Logger.warn('Night Shift: spawner found no "' + this.templateName + '" template; stopping.', 'Script')
      return
    }
    this._live.push(zombie)
  }

  /** A walkable point far enough from the player, or null if we could not find one this tick. */
  private _pickPoint(): number[] {
    const player = this._player ? this._player.worldPosition : null
    const far = (p: number[]) => !player
      || Math.hypot(p[0] - player[0], p[2] - player[2]) >= this.minPlayerDistance

    const mesh = this._navMesh()
    for (let i = 0; i < this.placementTries; i++) {
      const candidate = mesh ? this._randomOnMesh(mesh) : this._randomFallback()
      if (candidate && far(candidate)) return candidate
    }
    return null
  }

  private _navMesh(): any {
    for (const node of this.scene?.navMeshes ?? []) {
      const mesh = (node as any).mesh
      if (mesh && mesh.randomPoint) return mesh
    }
    return null
  }

  private _randomOnMesh(mesh: any): number[] {
    const out: number[] = [0, 0, 0]
    return mesh.randomPoint(out) ? [out[0], out[1], out[2]] : null
  }

  /**
   * No navmesh: scatter around an authored spawn point, else around the spawner itself. The Y is left
   * at the reference point's height and the capsule drops onto the ground, which is why `isGrounded`
   * reads false for the first fraction of a second — that is not a bug.
   */
  private _randomFallback(): number[] {
    const origin = this._points.length > 0
      ? this._points[Math.floor(Math.random() * this._points.length)].worldPosition
      : this.worldPosition
    const angle = Math.random() * Math.PI * 2
    const radius = this.fallbackRadius * Math.sqrt(Math.random())
    return [origin[0] + Math.sin(angle) * radius, origin[1], origin[2] + Math.cos(angle) * radius]
  }
}

import { Node } from 'cleo'

/**
 * Night Shift — a score pickup. Attach to the pickup's root node.
 *
 * ## The trigger has to be on a child
 *
 * A node registers `node.body || node.trigger` with the physics world — one or the other, and the body
 * wins. So a pickup that carried both would silently never fire. The template puts the trigger on a
 * dedicated `Trigger` child of the visual, and `onTrigger` is declared here on the child's script.
 *
 * This same class is attached to BOTH the visual root (for the bob and spin) and its trigger child (for
 * the pickup itself). `_isTrigger` decides which half runs, so there is only one file and one set of
 * tunables to keep in sync.
 *
 * ## Once, not once per frame
 *
 * The underlying contact event is guarded on the previous frame's collision matrix, so overlap does not
 * re-fire while you stand in it. It CAN fire again if contact is momentarily lost and regained across an
 * edge or a substep gap, which is exactly what happens when you walk the rim of a trigger — hence the
 * `_taken` latch. There is no exit event to pair with it.
 */
export default class NightShiftPickupNode extends Node {
  /** Points awarded. */
  public points: number = 100
  /** Degrees per second the visual spins. */
  public spinSpeed: number = 70
  /** Metres the visual rises and falls. */
  public bobHeight: number = 0.18
  /** Bobs per second. */
  public bobSpeed: number = 1.1

  private _taken: boolean = false
  private _isTrigger: boolean = false
  private _baseY: number = 0
  private _phase: number = 0
  private _director: Node = null

  onStart() {
    this._isTrigger = this.trigger !== null
    this._director = this.findNode('GameManager')
    this._baseY = this.position[1]
    // Desynchronise the bob so a field of pickups does not pulse in unison.
    this._phase = Math.random() * Math.PI * 2
  }

  onUpdate(delta: number, time: number) {
    if (this._isTrigger || this._taken) return
    this.rotateY(this.spinSpeed * delta)
    this.setY(this._baseY + Math.sin(time * this.bobSpeed * Math.PI * 2 + this._phase) * this.bobHeight)
  }

  onTrigger(other: Node) {
    if (this._taken || !other || !other.getVariable('isPlayer')) return
    this._taken = true
    this.collect()
  }

  /** Split out so a test can drive it without standing up a physics world. */
  public collect(): void {
    const director = this._director as any
    if (director && director.addScore) director.addScore(this.points)
    // The whole pickup goes, not just the trigger: `remove()` on a child would leave the visual behind.
    const root = this._isTrigger && this.parent ? this.parent : this
    root.remove()
  }
}

import { CharacterNode, Node } from 'cleo'

/**
 * Night Shift — a timed powerup. Same shape as `NightShiftPickup`: attach to the visual root for the bob
 * and spin, and to its `Trigger` child for the pickup itself.
 *
 * Three kinds, chosen by the `kind` field so one script and one template serve all of them:
 *
 *   speed        walk and run speed multiplied for a few seconds
 *   invincible   the zombie's damage check already reads `player.invincible`, so nothing else changes
 *   aoe          every zombie inside `radius` is ignited
 *
 * ## The AoE reuses the dawn burn
 *
 * It sets exactly the flag sunrise sets, so instakill and sunrise run one code path. The blast is
 * already tuned because dawn is tuned, and a zombie caught by both cannot die twice.
 *
 * ## Where the restore timer lives
 *
 * NOT here. `despawn()` and `remove()` cancel the node's own timers BEFORE `onDespawn` fires, so a
 * "give the speed back in 8 seconds" timer scheduled on the pickup that just removed itself would never
 * run, and the player would keep the buff for the rest of the level. The countdown lives on the player
 * instead, ticked in its own `onUpdate` — which also gives the HUD something to draw.
 */
export default class NightShiftPowerupNode extends Node {
  /** `speed`, `invincible` or `aoe`. */
  public kind: string = 'speed'
  /** Metres. Only used by `aoe`. */
  public radius: number = 14
  /** Trauma added to the camera rig on an AoE blast, 0..1. */
  public blastShake: number = 0.8
  public spinSpeed: number = 70
  public bobHeight: number = 0.18
  public bobSpeed: number = 1.1

  private _taken: boolean = false
  private _isTrigger: boolean = false
  private _baseY: number = 0
  private _phase: number = 0

  onStart() {
    this._isTrigger = this.trigger !== null
    this._baseY = this.position[1]
    this._phase = Math.random() * Math.PI * 2
  }

  onUpdate(delta: number, time: number) {
    if (this._isTrigger || this._taken) return
    this.rotateY(this.spinSpeed * delta)
    this.setY(this._baseY + Math.sin(time * this.bobSpeed * Math.PI * 2 + this._phase) * this.bobHeight)
  }

  onTrigger(other: Node) {
    if (this._taken || !other || !other.getVariable('isPlayer')) return
    this._taken = true
    this.collect(other)
  }

  /** Split out so a test can drive it without a physics world. */
  public collect(player: Node): void {
    const target = player as any
    if (this.kind === 'invincible') target.grantInvincibility?.()
    else if (this.kind === 'aoe') { target.flashAoe?.(); this._blast(player) }
    else target.grantSpeed?.()

    const root = this._isTrigger && this.parent ? this.parent : this
    root.remove()
  }

  /**
   * Ignite every zombie in range.
   *
   * `scene.characters` holds only SPAWNED characters, so a despawned or pooled zombie is not in it. The
   * player is in it too and is skipped by the same `isPlayer` marker the zombie brains filter on.
   */
  private _blast(player: Node): void {
    const origin = player.worldPosition
    for (const character of this.scene?.characters ?? []) {
      if (character.getVariable('isPlayer')) continue
      const zombie = character as any
      if (!zombie.ignite) continue
      const p = character.worldPosition
      if (Math.hypot(p[0] - origin[0], p[2] - origin[2]) > this.radius) continue
      zombie.ignite()
    }

    for (const rig of this.scene?.cameraRigs ?? []) rig.shake(this.blastShake)
  }
}

import { Game, Logger, Node, UIButtonNode, UIRootNode, UITextNode } from 'cleo'

/**
 * Night Shift — the end-of-level panel. Attach to the `EndScreen` node, a screen-space UI Root authored
 * with `visible: false`.
 *
 * Expected children:
 *
 *   Backdrop     uiPanel    stretched, interactive so it eats clicks meant for the world
 *     Card       uiStack    column, centred
 *       Title    uiText
 *       Items    uiText
 *       Score    uiText
 *       Buttons  uiStack    row
 *         Exit     uiButton
 *         Continue uiButton
 *
 * ## Why it is its own root and not a child of the HUD
 *
 * Setting `visible` walks the whole subtree and writes every descendant, so revealing a panel nested
 * inside the HUD would also force every HUD widget visible — including any you had deliberately hidden.
 * Keeping the two roots as siblings sidesteps that entirely.
 *
 * And `visible` is the right tool here rather than `despawn()`: the layout solve skips unspawned
 * children, but the DOM layer renders from the child list with no spawned filter, so a despawned inner
 * panel stays on screen frozen at its last solved rect.
 *
 * ## Buttons still work while the game is paused
 *
 * `Game.pause()` freezes every `onUpdate`, but not the UI layout pass, and clicks arrive through the DOM
 * rather than the node loop. So the panel lays out and responds with the game stopped behind it.
 */
export default class NightShiftEndScreenNode extends UIRootNode {
  public wonTitle: string = 'Dawn Breaks'
  public lostTitle: string = 'Game Over'
  public continueLabel: string = 'Continue'
  public retryLabel: string = 'Retry'
  public exitLabel: string = 'Exit'
  /** Scene the Exit button loads. There is no engine quit API; a menu is just another scene. */
  public menuScene: string = 'Main Menu'

  private _won: boolean = false

  onStart() {
    this.visible = false

    // `onPress` takes no arguments, and assigning it as an own property shadows the prototype method —
    // which is exactly how a script would have overridden it anyway.
    const exit = this._find('Exit') as UIButtonNode
    if (exit) {
      exit.label = this.exitLabel
      exit.onPress = () => this._exit()
    }
    const next = this._find('Continue') as UIButtonNode
    if (next) next.onPress = () => this._continue()
  }

  /** Called by the director. `won` picks the wording and which verb the second button gets. */
  public showResult(won: boolean, found: number, total: number, score: number, level: number): void {
    this._won = won

    this._text('Title', won ? this.wonTitle : this.lostTitle)
    this._text('Items', 'Items   ' + found + ' / ' + total)
    this._text('Score', 'Score   ' + score.toLocaleString())

    const next = this._find('Continue') as UIButtonNode
    if (next) next.label = won ? this.continueLabel : this.retryLabel

    // Reveal LAST, so nothing is drawn for a frame with the previous level's numbers in it.
    this.visible = true
  }

  private _continue(): void {
    // Won: the director already banked level+1, so re-loading this scene starts the next one. Lost: the
    // same load is a retry, because the level number was left alone.
    Game.resume()
    this._load(Game.sceneName)
  }

  private _exit(): void {
    Game.resume()
    this._load(this.menuScene)
  }

  private _load(scene: string): void {
    try { Game.loadScene(scene) }
    catch (e) { Logger.warn('Night Shift: could not load "' + scene + '": ' + e, 'Script') }
  }

  private _text(name: string, value: string): void {
    const node = this._find(name) as UITextNode
    if (node) node.text = value
  }

  private _find(name: string): Node {
    const walk = (node: Node): Node => {
      for (const child of node.children) {
        if (child.name === name) return child
        const found = walk(child)
        if (found) return found
      }
      return null
    }
    return walk(this)
  }
}

import { CameraRigNode, Input } from 'cleo'

/**
 * Third-person orbit camera — attach to the "Camera Pivot" child of the Playable.
 *
 *   Playable
 *   └── Camera Pivot  ← this script, on a **Camera Rig** node (Add → Cameras → Camera Rig)
 *       └── Camera    ← the rig positions it; do not move it by hand
 *
 * This extends CameraRigNode, so the rig owns the camera behaviour and this script owns only the
 * input wiring. What used to be script fields now lives in the **Camera Rig** inspector:
 *
 *   Arm Length ............... how far behind the pivot the camera sits (was `distance`)
 *   Yaw / Pitch Sensitivity .. degrees per pixel of mouse movement (was `lookSpeed`)
 *   Pitch Min / Max .......... vertical limits (was minPitch/maxPitch; -30 / 70 suits third person)
 *   Collision ................ on by default, and new: the camera now pulls in at walls and terrain
 *
 * The rig has **no follow target**: with `follow` unset it treats its own authored position as the
 * pivot, so parenting it under the Playable is all that is needed to make it ride the character.
 * (Setting Follow to the Playable instead would add positional damping, but the rig would then have
 * to leave the hierarchy, and ThirdPersonPlayable finds the pivot among its own children.)
 *
 * Why the pivot can own its heading at all: the Playable root never rotates — ThirdPersonPlayable
 * turns the Model, not itself — so this node's local yaw is also its world yaw, which is what the
 * controller reads to decide "forward". It reads `this.yaw`, not `rotation[1]`, because the euler value
 * is unusable past a quarter turn — the decomposition can only express |yaw| <= 90.
 *
 * The Controller finds this rig by walking the possessed character's subtree, so it no longer matters
 * what this node is called. The old `pivotName` match broke the moment anyone renamed it.
 */
export default class ThirdPersonCameraPivotNode extends CameraRigNode {
  /** Mouse-wheel zoom range, applied to the rig's Arm Length. */
  protected minDistance: number = 2
  protected maxDistance: number = 12
  protected zoomSpeed: number = 0.01

  onStart() {
    // Orbit mode means "yaw/pitch are whatever the script last set", so the rig will not fight the
    // input by recomputing the aim from a Look At target.
    this.aimMode = 'orbit'

    // The rig owns the camera child's entire local position (socket offset + arm), so a shoulder
    // offset authored by dragging the Camera in the viewport would be silently overwritten. Adopt it
    // as the rig's Socket Offset instead. Only X/Y are taken and Z is forced to 0 (Z is the arm's),
    // which makes this idempotent across reloads — re-reading an already-adopted offset is a no-op.
    // An offset already set in the inspector wins; this only rescues an un-migrated scene.
    const camera = this.children.find(child => child.nodeType === 'camera')
    const authored = camera ? camera.position : null
    const socketIsClear = Math.abs(this.socketOffset[0]) < 1e-3 && Math.abs(this.socketOffset[1]) < 1e-3
    if (authored && socketIsClear && (Math.abs(authored[0]) > 1e-3 || Math.abs(authored[1]) > 1e-3))
      this.socketOffset = [authored[0], authored[1], 0]

    this.armLength = Math.max(this.minDistance, Math.min(this.maxDistance, this.armLength))
  }

  onUpdate(delta: number, time: number) {
    // NO addYaw/addPitch here any more. The Controller possessing the character drives this rig's aim,
    // in the scene's control pass — before the character reads it, which is what removes the frame of
    // lag this script used to have between a camera swing and the strafe that should match it.
    //
    // Two writers on one rig is a camera that moves at DOUBLE speed, so if you want to steer it from a
    // script instead, turn off "Drive the camera rig" on the Controller first.
    //
    // Zoom stays here: how far back the camera sits is a game decision, not a control-scheme one.
    // `Zoom` is bound to the wheel and to a pinch, and it needs no "is the pointer over the canvas"
    // check — the wheel listener lives on the canvas, so an event the canvas never received never
    // arrives here.
    const zoom = Input.value('Zoom')
    if (zoom !== 0) {
      const next = this.armLength + zoom * this.zoomSpeed
      this.armLength = Math.max(this.minDistance, Math.min(this.maxDistance, next))
    }

    // No _apply() any more. The rig writes its own rotation and the camera child's position in the
    // scene's late pass, which runs after every onUpdate — so it always acts on this frame's input,
    // and the camera can no longer lag the character by a frame.
  }
}
